<?php
session_start();
$api = rtrim(getenv('MONITOR_API_URL') ?: 'http://api:3000','/');
function api_get(string $path): array { global $api; $ch=curl_init($api.$path); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>8]); $body=curl_exec($ch); $code=curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch); if($body===false||$code>=400)return ['error'=>'API unavailable','status'=>$code]; return json_decode($body,true) ?: []; }
$summary=api_get('/api/v1/dashboard/summary'); $hosts=api_get('/api/v1/hosts'); $alerts=api_get('/api/v1/alerts');
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Infrastructure Monitoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><span class="navbar-brand">Infrastructure Monitoring</span><a class="btn btn-outline-light btn-sm" href="admin.php">Admin</a></div></nav><main class="container-fluid p-4"><div class="row g-3 mb-4"><div class="col"><div class="card"><div class="card-body"><small>Total Hosts</small><h2><?=e($summary['hosts']['total']??0)?></h2></div></div></div><div class="col"><div class="card"><div class="card-body"><small>Online</small><h2 class="text-success"><?=e($summary['hosts']['online']??0)?></h2></div></div></div><div class="col"><div class="card"><div class="card-body"><small>Warning</small><h2 class="text-warning"><?=e($summary['hosts']['warning']??0)?></h2></div></div></div><div class="col"><div class="card"><div class="card-body"><small>Critical</small><h2 class="text-danger"><?=e($summary['hosts']['critical']??0)?></h2></div></div></div><div class="col"><div class="card"><div class="card-body"><small>Open Alerts</small><h2><?=e($summary['alerts']['open_alerts']??0)?></h2></div></div></div></div><div class="card mb-4"><div class="card-header">Hosts</div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Name</th><th>Hostname</th><th>Status</th><th>Last Seen</th></tr></thead><tbody><?php foreach(($hosts??[]) as $h):?><tr><td><?=e($h['name'])?></td><td><?=e($h['hostname'])?></td><td><span class="badge text-bg-<?=($h['status']==='ONLINE'?'success':($h['status']==='CRITICAL'?'danger':'warning'))?>"><?=e($h['status'])?></span></td><td><?=e($h['last_seen'])?></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><div class="card-header">Recent Alerts</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Host</th><th>Severity</th><th>Status</th><th>Title</th><th>Started</th></tr></thead><tbody><?php foreach(($alerts??[]) as $a):?><tr><td><?=e($a['host_name'])?></td><td><?=e($a['severity'])?></td><td><?=e($a['status'])?></td><td><?=e($a['title'])?></td><td><?=e($a['started_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
